import{_ as t,o as a,c as n,ag as o}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"Polling multiplayer","description":"","frontmatter":{},"headers":[],"relativePath":"UncivCN/Polling-multiplayer.md","filePath":"UncivCN/Polling-multiplayer.md"}'),i={name:"UncivCN/Polling-multiplayer.md"};function r(l,e,d,s,h,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="polling-multiplayer" tabindex="-1">Polling multiplayer <a class="header-anchor" href="#polling-multiplayer" aria-label="Permalink to &quot;Polling multiplayer&quot;">​</a></h1><blockquote><p>Author: AutumnPizazz</p><p>Date: 2026-05-21</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Polling multiplayer is a new multiplayer mode that UncivCN adds on top of the original dynamic-turn system. Original multiplayer is strictly sequential: after the current player finishes their turn and clicks &quot;next turn&quot;, the save is passed on only after AI resolution — the wait depends on how long the opponent takes. Polling multiplayer splits the same turn into fixed-length time slices and passes the save between players slice by slice, capping the wait from &quot;as long as the opponent wants&quot; to a few seconds.</p><p>It is a purely additive feature — without a polling interval selected, behavior is identical to the original, and old saves load normally.</p><h2 id="enabling" tabindex="-1">Enabling <a class="header-anchor" href="#enabling" aria-label="Permalink to &quot;Enabling&quot;">​</a></h2><p>When creating a new game, check <strong>Online Multiplayer</strong>; a <strong>Polling interval</strong> dropdown appears below it:</p><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td>Off</td><td>Polling disabled, original dynamic turns</td></tr><tr><td>5s / 10s / 15s / 20s / 30s</td><td>Length of each player&#39;s action window per slice</td></tr></tbody></table><p>The host picks an interval and creates the game; the whole game then runs in polling rhythm.</p><h2 id="game-flow" tabindex="-1">Game flow <a class="header-anchor" href="#game-flow" aria-label="Permalink to &quot;Game flow&quot;">​</a></h2><h3 id="rotation-within-a-turn" tabindex="-1">Rotation within a turn <a class="header-anchor" href="#rotation-within-a-turn" aria-label="Permalink to &quot;Rotation within a turn&quot;">​</a></h3><p>When a turn starts, the current player gets an action window, during which units and cities can be operated normally. When the window ends:</p><ul><li><strong>Player clicks &quot;I&#39;m done&quot;</strong>: the player is marked as finished for this turn and the save is passed to the next unfinished player; that player is no longer polled this turn.</li><li><strong>Timer expires</strong>: the save is automatically passed to the next unfinished player, but the current player is <strong>not</strong> marked finished — when the rotation comes back they can keep playing.</li><li><strong>Only one unfinished player left</strong>: that player is no longer switched away from; the timer keeps resetting until they click &quot;I&#39;m done&quot;.</li></ul><h3 id="turn-advancement" tabindex="-1">Turn advancement <a class="header-anchor" href="#turn-advancement" aria-label="Permalink to &quot;Turn advancement&quot;">​</a></h3><p>When all surviving human players have clicked &quot;I&#39;m done&quot;, the turn advances: each human player&#39;s turn is ended in order, all AI civilizations are processed, finish flags are reset, and a new rotation starts for all human players of the new turn.</p><h3 id="countdown-display" tabindex="-1">Countdown display <a class="header-anchor" href="#countdown-display" aria-label="Permalink to &quot;Countdown display&quot;">​</a></h3><p>The top bar shows the seconds left in the current window next to the turn counter, color-coded by remaining time:</p><ul><li>Green: more than half remaining</li><li>Gold: 25% to half remaining</li><li>Coral: less than 25% remaining</li></ul><p>It is hidden when it is not your turn or when not in polling mode.</p><h2 id="technical-implementation" tabindex="-1">Technical implementation <a class="header-anchor" href="#technical-implementation" aria-label="Permalink to &quot;Technical implementation&quot;">​</a></h2><h3 id="save-passing" tabindex="-1">Save passing <a class="header-anchor" href="#save-passing" aria-label="Permalink to &quot;Save passing&quot;">​</a></h3><p>Polling multiplayer reuses the original multiplayer upload/download infrastructure. At each window end, the current player uploads the modified full game state to the server; the next player detects the update via polling or WebSocket push and downloads it. Only one player holds the action rights at any time, so no merge conflicts need handling.</p><h3 id="websocket-push" tabindex="-1">WebSocket push <a class="header-anchor" href="#websocket-push" aria-label="Permalink to &quot;WebSocket push&quot;">​</a></h3><p>To reduce polling latency, clients automatically establish a WebSocket connection when entering polling multiplayer. After a player uploads the save, the server immediately pushes a <code>GameUpdated</code> message to all online clients in the room, triggering an immediate download of the latest state. This reuses the existing chat WebSocket endpoint; no extra configuration needed.</p><h3 id="new-fields" tabindex="-1">New fields <a class="header-anchor" href="#new-fields" aria-label="Permalink to &quot;New fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Location</th><th>Description</th></tr></thead><tbody><tr><td><code>pollingIntervalSeconds</code></td><td><code>GameParameters</code></td><td>Polling interval in seconds; 0 = disabled</td></tr><tr><td><code>playersFinishedThisTurn</code></td><td><code>GameInfo</code></td><td>Set of civ IDs that confirmed finished this turn</td></tr></tbody></table><h3 id="server-side-changes" tabindex="-1">Server-side changes <a class="header-anchor" href="#server-side-changes" aria-label="Permalink to &quot;Server-side changes&quot;">​</a></h3><p>The server <code>Response</code> type gains a <code>GameUpdated</code> message, broadcast to all WebSocket subscribers of the room after a successful file upload.</p><h3 id="related-files" tabindex="-1">Related files <a class="header-anchor" href="#related-files" aria-label="Permalink to &quot;Related files&quot;">​</a></h3><p>Core logic spans the following source files:</p><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>GameParameters.kt</code></td><td>new <code>pollingIntervalSeconds</code> field</td></tr><tr><td><code>GameInfo.kt</code></td><td>new <code>playersFinishedThisTurn</code> set, <code>nextTurnPolling()</code> and helper queries</td></tr><tr><td><code>NextTurnAction.kt</code></td><td>new <code>FinishAction</code> enum value</td></tr><tr><td><code>NextTurnButton.kt</code></td><td>button text appends countdown in polling mode</td></tr><tr><td><code>WorldScreen.kt</code></td><td>new timer coroutine, <code>finishPollingTurn()</code> / <code>passPollingTurn()</code></td></tr><tr><td><code>WorldScreenTopBarResources.kt</code></td><td>top-bar countdown display</td></tr><tr><td><code>GameOptionsTable.kt</code></td><td>polling interval selector on the game-creation screen</td></tr><tr><td><code>Multiplayer.kt</code></td><td>null-safety fix for <code>GameInfoPreview.isUsersTurn()</code></td></tr><tr><td><code>MultiplayerGamePreview.kt</code></td><td>null-safety fix for <code>GameInfoPreview.getCurrentPlayerCiv()</code></td></tr><tr><td><code>ChatWebSocket.kt</code></td><td>client-side <code>GameUpdated</code> reception and refresh trigger</td></tr><tr><td><code>UncivServer.kt</code></td><td>server-side WebSocket broadcast after upload</td></tr><tr><td><code>GameSettings.kt</code></td><td>default password set to 123456</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>All players in a polling game must configure the multiplayer password in game settings (default 123456), otherwise WebSocket authentication failures affect push delivery.</li><li>Adjust the interval to the number of players: 5–10s for 2 players; 15s+ recommended for 4 or more.</li><li>The server must run with the <code>-chat</code> option (on by default) to support WebSocket push.</li></ul>',33)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
